        raise ValueError("Input must be bytes or bytearray")

    results = []
    buffer = bytearray()
    hunting = True
    escaped = False

    def check_frame():
        nonlocal buffer
        # Frame must have at least 3 bytes: 1 payload + 2 CRC
        if len(buffer) < 3:
            raise ValueError("Frame too short")

        # Payload is everything except last 2 bytes
        payload = buffer[:-2]
        # CRC bytes
        crc_bytes = buffer[-2:]

        # Payload must be at least 1 byte
        if len(payload) < 1:
            raise ValueError("Payload too short")

        # Calculate CRC-16/CCITT-FALSE
        crc = 0xFFFF
        for byte in payload:
            crc ^= (byte << 8)
            for _ in range(8):
                if crc & 0x8000:
                    crc = (crc << 1) ^ 0x1021
                else:
                    crc = (crc << 1)
                crc &= 0xFFFF

        # Compare with received CRC (big-endian)
        received_crc = (crc_bytes[0] << 8) | crc_bytes[1]
        if crc != received_crc:
            raise ValueError("CRC mismatch")

        results.append(bytes(payload))
        buffer.clear()

