                # Since buffer is empty, it's effectively a repeated flag or start of new frame
                # If we were hunting, this would start a frame, but we can't be hunting if we processed an escape
                # (Escape only happens inside frame).
                # So we are inside a frame, buffer empty.
                pass 
            elif byte == 0x5E:
                buffer.append(0x7E)
            elif byte == 0x5D:
                buffer.append(0x7D)
            else:
                raise ValueError("Invalid escape sequence")
        else:
