def markov_run(program, text, limit):
    # Input validation
    if not isinstance(program, str):
        raise ValueError("program must be a string")
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError("limit must be a non-negative integer")

    def parse_pattern(s):
        """Parses a pattern string according to Markov algorithm rules."""
        if '"' not in s:
            return s
        # If it contains quotes, it must be exactly one quoted string
        if not s.startswith('"') or not s.endswith('"'):
            raise ValueError("Pattern must be a quoted string or unquoted literal")
        if len(s) < 2:
            raise ValueError("Pattern string is too short")

        content = s[1:-1]
        result = []
        i = 0
        while i < len(content):
            c = content[i]
            if c == '\\':
                if i + 1 >= len(content):
                    raise ValueError("Backslash at end of quoted string")
                next_c = content[i+1]
                if next_c == '"':
                    result.append('"')
                elif next_c == '\\':
                    result.append('\\')
                elif next_c == 'n':
                    result.append('\n')
                elif next_c == 't':
                    result.append('\t')
                else:
                    raise ValueError(f"Invalid escape sequence \\{next_c}")
                i += 2
            elif c == '"':
                raise ValueError("Unescaped quote inside quoted string")
            else:
                result.append(c)
                i += 1
        return "".join(result)

    # Parse the program
    rules = []
    lines = program.split("\n")
    for line in lines:
        # Strip spaces, tabs, and \r from both ends
        line = line.strip(" \t\r")

        # Skip empty lines or comments
        if not line or line.startswith("#"):
            continue

        # Find the first "->" not inside a quoted string
        arrow_idx = -1
        in_quote = False
        i = 0
        n = len(line)

        while i < n:
            char = line[i]
            if in_quote:
                if char == '\\':
                    # Inside a quoted string, backslash escapes the next character
                    i += 2
                    continue
                elif char == '"':
                    in_quote = False
            else:
                if char == '"':
                    in_quote = True
                elif char == '-' and i + 1 < n and line[i+1] == '>':
                    arrow_idx = i
                    break
            i += 1

        if arrow_idx == -1:
            raise ValueError(f"No arrow found in line: {line}")

        if in_quote:
            raise ValueError(f"Unterminated quote in line: {line}")

        lhs_str = line[:arrow_idx]
        rhs_str = line[arrow_idx + 2:]

        # Check for terminating rule
        is_terminating = False
        if rhs_str.startswith('.'):
            is_terminating = True
            rhs_str = rhs_str[1:]

        # Parse LHS and RHS patterns
        lhs_pattern = parse_pattern(lhs_str)
        rhs_pattern = parse_pattern(rhs_str)

        rules.append((lhs_pattern, rhs_pattern, is_terminating))

    # Initial text length check
    if len(text) > 10000:
        raise ValueError("Text length exceeds 10000 characters")

    steps = 0
    while True:
        # Check limit: a step that would be the (limit+1)-th is an error
        if steps >= limit:
            raise ValueError("Step limit exceeded")

        # Find the first rule whose LHS occurs in the text
        found_rule = None
        match_idx = -1

        for lhs, rhs, term in rules:
            if lhs == "":
                # Empty LHS occurs everywhere at index 0
                match_idx = 0
                found_rule = (lhs, rhs, term)
                break
            else:
                idx = text.find(lhs)
                if idx != -1:
                    match_idx = idx
                    found_rule = (lhs, rhs, term)
                    break

        if found_rule is None:
            # No rule applies
            return (text, steps)

        lhs, rhs, term = found_rule

        # Replace the leftmost occurrence
        text = text[:match_idx] + rhs + text[match_idx + len(lhs):]
        steps += 1

        # Check text length after step
        if len(text) > 10000:
            raise ValueError("Text length exceeds 10000 characters")

        # If terminating rule, return immediately
        if term:
            return (text, steps)

