    result = {}
    i = 0
    n = len(text)

    while i < n:
        # Find end of natural line
        end = i
        while end < n:
            if text[end] == '\r':
                end += 1
                if end < n and text[end] == '\n':
                    end += 1
                break
            elif text[end] == '\n':
                end += 1
                break
            else:
                end += 1

        natural_line = text[i:end]
        # Remove terminator if present
        if end > i:
            if natural_line[-1] == '\n':
                if len(natural_line) > 1 and natural_line[-2] == '\r':
