        rest = rest.lstrip(' \t\f')

        # Check for separator
        if rest and rest[0] in ('=', ':'):
            rest = rest[1:]
            rest = rest.lstrip(' \t\f')

        value = rest

        key = process_escapes(key)
        value = process_escapes(value)

        result[key] = value

    return result

def ustar_entries(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes or bytearray")

    length = len(data)
    if length == 0:
        raise ValueError("Empty data")
    if length % 512 != 0:
        raise ValueError("Data length must be multiple of 512")

    entries = []
    offset = 0

    def parse_octal(field):
        i = 0
        n = len(field)
        # Skip leading spaces
        while i < n and field[i] == 0x20:
            i += 1
        if i == n:
            raise ValueError("Octal field has no digits")

        val = 0
        while i < n:
            b = field[i]
            if 0x30 <= b <= 0x37:
                val = (val << 3) + (b - 0x30)
                i += 1
            elif b == 0x20 or b == 0x00:
                # Check remaining bytes
                while i < n:
                    if field[i] != 0x20 and field[i] != 0x00:
                        raise ValueError("Invalid trailing byte in octal field")
                    i += 1
                return val
            else:
                raise ValueError("Invalid character in octal field")
        return val

