        idx = field.find(b'\x00')
        if idx != -1:
            sub = field[:idx]
        else:
            sub = field
        return sub.decode('utf-8')

    while offset < length:
        if length - offset < 512:
            raise ValueError("Truncated block")

        block = data[offset : offset + 512]

        # Check for zero block
        if all(b == 0 for b in block):
            if length - (offset + 512) < 512:
                raise ValueError("Zero block not followed by second zero block")
            next_block = data[offset + 512 : offset + 1024]
            if not all(b == 0 for b in next_block):
                raise ValueError("First zero block not followed by second zero block")
