        tf = block[156]
        if tf == 0 or tf == 48: # NUL or '0'
            kind = "file"
        elif tf == 53: # '5'
            kind = "dir"
        elif tf == 50: # '2'
            kind = "symlink"
        elif tf == 49: # '1'
            kind = "hardlink"
        else:
            raise ValueError(f"Invalid typeflag {tf}")

