import struct

def msgpack_loads(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes or bytearray")

    pos = 0
    length = len(data)
    depth = 0

    def read_bytes(n):
        nonlocal pos
        if pos + n > length:
            raise ValueError("unexpected end of data")
        val = data[pos:pos+n]
        pos += n
        return val

    def read_uint(n):
        raw = read_bytes(n)
        return int.from_bytes(raw, 'big')

    def load():
        nonlocal depth
        if pos >= length:
            raise ValueError("unexpected end of data")
        if depth > 16:
            raise ValueError("max nesting depth exceeded")

        b = data[pos]
        pos += 1

        if 0x00 <= b <= 0x7f:
            return b
        elif 0xe0 <= b <= 0xff:
            return b - 256
        elif 0x80 <= b <= 0x8f:
            return load_map(b & 0x0f, True)
        elif 0x90 <= b <= 0x9f:
            return load_array(b & 0x0f, True)
        elif 0xa0 <= b <= 0xbf:
            return load_str(b & 0x1f, True)
        elif b == 0xc0:
            return None
        elif b == 0xc2:
            return False
        elif b == 0xc3:
            return True
        elif b == 0xc4:
            return load_bin(1)
        elif b == 0xc5:
            return load_bin(2)
        elif b == 0xc6:
            return load_bin(4)
        elif b == 0xca:
            raw = read_bytes(4)
            return struct.unpack('>f', raw)[0]
        elif b == 0xcb:
            raw = read_bytes(8)
            return struct.unpack('>d', raw)[0]
        elif b == 0xcc:
            return read_uint(1)
        elif b == 0xcd:
            return read_uint(2)
        elif b == 0xce:
            return read_uint(4)
        elif b == 0xcf:
            return read_uint(8)
        elif b == 0xd0:
            raw = read_bytes(1)
            return int.from_bytes(raw, 'big', signed=True)
        elif b == 0xd1:
            raw = read_bytes(2)
            return int.from_bytes(raw, 'big', signed=True)
        elif b == 0xd2:
            raw = read_bytes(4)
            return int.from_bytes(raw, 'big', signed=True)
        elif b == 0xd3:
            raw = read_bytes(8)
            return int.from_bytes(raw, 'big', signed=True)
        elif b == 0xd9:
            return load_str(1, False)
        elif b == 0xda:
            return load_str(2, False)
        elif b == 0xdb:
            return load_str(4, False)
        elif b == 0xdc:
            return load_array(2, False)
        elif b == 0xdd:
            return load_array(4, False)
        elif b == 0xde:
            return load_map(2, False)
        elif b == 0xdf:
            return load_map(4, False)
        else:
            raise ValueError(f"unknown type byte: {b:#04x}")

    def load_array(count_or_len, is_fixed):
        nonlocal depth, pos
        if is_fixed:
            count = count_or_len
        else:
            count = read_uint(count_or_len)

        remaining = length - pos
        if count > remaining:
            raise ValueError("array count exceeds remaining data")

        depth += 1
        try:
            arr = []
            for _ in range(count):
                arr.append(load())
            return arr
        finally:
            depth -= 1

    def load_map(count_or_len, is_fixed):
        nonlocal depth, pos
        if is_fixed:
            count = count_or_len
        else:
            count = read_uint(count_or_len)

        remaining = length - pos
        if count * 2 > remaining:
            raise ValueError("map count exceeds remaining data")

        depth += 1
        try:
            d = {}
            for _ in range(count):
                key = load()
                val = load()
                if isinstance(key, bool) or not isinstance(key, (str, int)):
                    raise ValueError("map key must be str or int")
                if key in d:
                    raise ValueError("duplicate map key")
                d[key] = val
            return d
        finally:
            depth -= 1

    def load_str(nbytes_len, is_fixed):
        nonlocal pos
        if is_fixed:
            length_str = nbytes_len
        else:
            length_str = read_uint(nbytes_len)

        if pos + length_str > length:
            raise ValueError("str length exceeds data")

        raw = data[pos:pos+length_str]
        pos += length_str
        try:
            return raw.decode('utf-8')
        except UnicodeDecodeError:
            raise ValueError("invalid UTF-8")

    def load_bin(nbytes_len):
        nonlocal pos
        length_bin = read_uint(nbytes_len)
        if pos + length_bin > length:
            raise ValueError("bin length exceeds data")

        raw = data[pos:pos+length_bin]
        pos += length_bin
        return raw

    result = load()
    if pos != length:
        raise ValueError("trailing data")
    return result

