            return b
        elif 0xe0 <= b <= 0xff:
            return b - 256
        elif 0x80 <= b <= 0x8f:
            return load_map(b & 0x0f, True)
        elif 0x90 <= b <= 0x9f:
            return load_array(b & 0x0f, True)
        elif 0xa0 <= b <= 0xbf:
            return load_str(b & 0x1f, True)
