        # Check if count is too large for remaining data (min 1 byte per element)
        remaining = limit - pos[0]
        if count > remaining:
            raise ValueError("Array count too large for remaining data")

        result = []
        for _ in range(count):
            val, pos[0] = parse(depth)
            result.append(val)
        return result, pos[0]

    def parse_map(count, depth):
        # Check if count * 2 (key-value pairs) fits in remaining data (min 1 byte per item)
        remaining = limit - pos[0]
        if count * 2 > remaining:
            raise ValueError("Map count too large for remaining data")

        result = {}
        for _ in range(count):
            # Parse key
            key_val, pos[0] = parse(depth)

            # Validate key type
            if isinstance(key_val, bool):
                raise ValueError("Bool keys not allowed")
            if not isinstance(key_val, (str, int)):
                raise ValueError("Invalid map key type")

            # Check for duplicate keys
            if key_val in result:
                raise ValueError("Duplicate map key")

            # Parse value
            val_val, pos[0] = parse(depth)
            result[key_val] = val_val

        return result, pos[0]

    # Parse the single value
    value, end_pos = parse(0)

    # Ensure no extra bytes
    if end_pos != limit:
        raise ValueError("Trailing bytes after value")

    return value

