    # Days in full years before y
    years = y - 1
    leaps = years // 4 - years // 100 + years // 400
    total = years * 365 + leaps
    # Days in current year
    for i in range(1, m):
        total += days_in_gregorian_month(y, i)
    total += d
    return total

