    y = int(y)
    if y < 1:
        y = 1

    # Find exact year
    # Check bounds first
    max_ordinal = gregorian_to_ordinal(9999, 12, 31)
    min_ordinal = 1

    if ordinal < min_ordinal or ordinal > max_ordinal:
        return None # Should be handled by caller

