import math

def timer_sched(timers, cancels, mutes, until, k):
    # --- Validation ---
    if not isinstance(timers, (list, tuple)): raise ValueError
    if not isinstance(cancels, (list, tuple)): raise ValueError
    if not isinstance(mutes, (list, tuple)): raise ValueError
    if not isinstance(until, int) or not isinstance(k, int): raise ValueError
    if not (0 <= until <= 10**12): raise ValueError
    if not (0 <= k <= 200): raise ValueError
    if len(timers) > 30: raise ValueError
    if len(cancels) > 60: raise ValueError
    if len(mutes) > 60: raise ValueError

    timer_names = set()
    timer_map = {}
    for idx, t in enumerate(timers):
        if not isinstance(t, tuple) or len(t) != 5: raise ValueError
        name, start, period, count, prio = t
        if not isinstance(name, str) or not name: raise ValueError
        if name in timer_names: raise ValueError
        if not isinstance(start, int) or not (0 <= start <= 10**12): raise ValueError
        if not isinstance(period, int) or not (0 <= period <= 10**12): raise ValueError
        if not isinstance(count, int) or not (1 <= count <= 10**12): raise ValueError
        if not isinstance(prio, int) or not (-100 <= prio <= 100): raise ValueError
        if period == 0 and count != 1: raise ValueError
        timer_names.add(name)
        timer_map[name] = (start, period, count, prio, idx)

    cancel_map = {}
    for c in cancels:
        if not isinstance(c, tuple) or len(c) != 3: raise ValueError
        name, t, mode = c
        if name not in timer_names: raise ValueError
        if not isinstance(t, int) or not (0 <= t <= 10**12): raise ValueError
        if mode not in ("before", "after"): raise ValueError
        if name not in cancel_map:
            cancel_map[name] = {"before": [], "after": []}
        cancel_map[name][mode].append(t)

    for name, modes in cancel_map.items():
        if modes["before"]:
            cancel_map[name] = (min(modes["before"]), False)
        elif modes["after"]:
            cancel_map[name] = (min(modes["after"]), True)
        else:
            del cancel_map[name]

    merged_mutes = []
    for m in mutes:
        if not isinstance(m, tuple) or len(m) != 2: raise ValueError
        a, b = m
        if not isinstance(a, int) or not isinstance(b, int): raise ValueError
        if not (0 <= a < b <= 10**12): raise ValueError
        merged_mutes.append((a, b))
    merged_mutes.sort()

    # Merge overlapping/touching intervals
    final_mutes = []
    for a, b in merged_mutes:
        if final_mutes and a <= final_mutes[-1][1]:
            final_mutes[-1] = (final_mutes[-1][0], max(final_mutes[-1][1], b))
        else:
            final_mutes.append((a, b))

    # --- Processing ---
    groups = []
    for name, (start, period, count, prio, t_idx) in timer_map.items():
        # Generate intervals of s
        intervals = []
        prev = 0
        for a, b in final_mutes:
            if prev < a:
                intervals.append((prev, a, None))
            intervals.append((a, b, b))
            prev = b
        if prev < until:
            intervals.append((prev, until, None))

        for L, R, d_const in intervals:
            if period == 0:
                if L <= start < R:
                    d0 = d_const if d_const is not None else start
                    cnt = 1
                    groups.append((d0, 0, name, 0, cnt, prio, t_idx))
            else:
                i_min = max(0, (L - start + period - 1) // period)
                i_max = min(count - 1, (R - 1 - start) // period)
                if i_min <= i_max:
                    cnt = i_max - i_min + 1
                    d0 = d_const if d_const is not None else start + i_min * period
                    groups.append((d0, period, name, i_min, cnt, prio, t_idx))

    # Apply cancels and until
    for g in groups:
        d0, period, name, i0, cnt, prio, t_idx = g
        # Filter by until
        if d0 >= until:
            continue
        if period == 0:
            cnt = 0 if d0 >= until else 1
        else:
            cnt = min(cnt, (until - 1 - d0) // period + 1)

        # Filter by cancel
        if name in cancel_map:
            thresh, strict = cancel_map[name]
            if strict: # after: blocks d > thresh => keeps d <= thresh
                if period == 0:
                    cnt = 0 if d0 > thresh else 1
                else:
                    cnt = min(cnt, (thresh - d0) // period + 1)
            else: # before: blocks d >= thresh => keeps d < thresh
                if period == 0:
                    cnt = 0 if d0 >= thresh else 1
                else:
                    cnt = min(cnt, (thresh - 1 - d0) // period + 1)

        if cnt > 0:
            groups[groups.index(g)] = (d0, period, name, i0, cnt, prio, t_idx)

    # Sort groups
    groups.sort(key=lambda x: (x[0], x[5], x[3], x[6]))

    log = []
    counts = {name: 0 for name in timer_map}
    delivered = 0

    for d0, period, name, i0, cnt, prio, t_idx in groups:
        for j in range(cnt):
            if delivered >= k:
                break
            d = d0 + j * period
            i = i0 + j
            log.append((d, name, i))
            counts[name] += 1
            delivered += 1
        if delivered >= k:
            break

    return {"log": log, "counts": counts}

import bisect
import heapq

def timer_sched(timers, cancels, mutes, until, k):
    # --- Validation ---
    def check_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    if not isinstance(timers, (list, tuple)): raise ValueError
    if not isinstance(cancels, (list, tuple)): raise ValueError
    if not isinstance(mutes, (list, tuple)): raise ValueError
    if not check_int(until) or not check_int(k): raise ValueError
    if not (0 <= until <= 10**12): raise ValueError
    if not (0 <= k <= 200): raise ValueError
    if len(timers) > 30: raise ValueError
    if len(cancels) > 60: raise ValueError
    if len(mutes) > 60: raise ValueError

    timer_names = set()
    timer_map = {}
    for idx, t in enumerate(timers):
        if not isinstance(t, tuple) or len(t) != 5: raise ValueError
        name, start, period, count, prio = t
        if not isinstance(name, str) or not name: raise ValueError
        if name in timer_names: raise ValueError
        if not check_int(start) or not (0 <= start <= 10**12): raise ValueError
        if not check_int(period) or not (0 <= period <= 10**12): raise ValueError
        if not check_int(count) or not (1 <= count <= 10**12): raise ValueError
        if not check_int(prio) or not (-100 <= prio <= 100): raise ValueError
        if period == 0 and count != 1: raise ValueError
        timer_names.add(name)
        timer_map[name] = (start, period, count, prio, idx)

    cancel_map = {}
    for c in cancels:
        if not isinstance(c, tuple) or len(c) != 3: raise ValueError
        name, t, mode = c
        if name not in timer_names: raise ValueError
        if not check_int(t) or not (0 <= t <= 10**12): raise ValueError
        if mode not in ("before", "after"): raise ValueError
        if name not in cancel_map:
            cancel_map[name] = {"before": [], "after": []}
        cancel_map[name][mode].append(t)

    timer_limits = {}
    for name, modes in cancel_map.items():
        lim = 10**18  # effectively infinity
        if modes["before"]:
            lim = min(lim, min(modes["before"]) - 1)
        if modes["after"]:
            lim = min(lim, min(modes["after"]))
        timer_limits[name] = lim

    merged_mutes = []
    for m in mutes:
        if not isinstance(m, tuple) or len(m) != 2: raise ValueError
        a, b = m
        if not check_int(a) or not check_int(b): raise ValueError
        if not (0 <= a < b <= 10**12): raise ValueError
        merged_mutes.append((a, b))
    merged_mutes.sort()

    # Merge overlapping/touching intervals
    final_mutes = []
    for a, b in merged_mutes:
        if final_mutes and a <= final_mutes[-1][1]:
            final_mutes[-1] = (final_mutes[-1][0], max(final_mutes[-1][1], b))
        else:
            final_mutes.append((a, b))

    mute_A = [x[0] for x in final_mutes]
    mute_B = [x[1] for x in final_mutes]

    def get_d(s):
        idx = bisect.bisect_right(mute_A, s) - 1
        if idx >= 0 and s < mute_B[idx]:
            return mute_B[idx]
        return s

    # Prepare timer data with limits
    timer_data = {}
    for name, (start, period, count, prio, t_idx) in timer_map.items():
        lim = timer_limits.get(name, 10**18)
        limit = min(until - 1, lim)
        timer_data[name] = (start, period, count, prio, t_idx, limit)

    # --- Compute Counts Analytically ---
    counts = {name: 0 for name in timer_map}
    for name, (start, period, count, prio, t_idx, limit) in timer_data.items():
        if limit < start:
            continue
        # Find max valid s
        s_max = limit
        for A, B in final_mutes:
            if B > limit:
                s_max = min(s_max, A - 1)
            if A > limit:
                break
        if s_max < start:
            continue
        if period == 0:
            counts[name] = 1 if start <= s_max else 0
        else:
            i_max = min(count - 1, (s_max - start) // period)
            counts[name] = i_max + 1

    # --- Generate Log using Heap ---
    heap = []
    for name, (start, period, count, prio, t_idx, limit) in timer_data.items():
        if start <= limit:
            d = get_d(start)
            if d <= limit:
                heapq.heappush(heap, (d, prio, start, t_idx, name, 0))

    log = []
    delivered = 0
    while heap and delivered < k:
        d, prio, s, t_idx, name, i = heapq.heappop(heap)
        log.append((d, name, i))
        delivered += 1

        _, period, count, _, _, limit = timer_data[name]
        if i + 1 < count:
            next_s = s + period
            next_d = get_d(next_s)
            if next_d <= limit:
                heapq.heappush(heap, (next_d, prio, next_s, t_idx, name, i + 1))

    return {"log": log, "counts": counts}

def book_rooms(rooms, requests):
    if not isinstance(rooms, (list, tuple)) or not isinstance(requests, (list, tuple)):
        raise ValueError("Invalid input types")
    if not (1 <= len(rooms) <= 20):
        raise ValueError("Invalid number of rooms")
    if len(requests) > 200:
        raise ValueError("Too many requests")

    room_names = []
    room_info = {}
    for i, r in enumerate(rooms):
        if not isinstance(r, tuple) or len(r) != 3:
            raise ValueError("Invalid room tuple")
        name, cap, gap = r
        if not isinstance(name, str) or not name:
            raise ValueError("Invalid room name")
        if name in room_names:
            raise ValueError("Duplicate room name")
        if not isinstance(cap, int) or not (1 <= cap <= 1000):
            raise ValueError("Invalid capacity")
        if not isinstance(gap, int) or not (0 <= gap <= 10**9):
            raise ValueError("Invalid gap")
        room_names.append(name)
        room_info[name] = (cap, gap, i)

    request_ids = set()
    for req in requests:
        if not isinstance(req, tuple) or len(req) != 6:
            raise ValueError("Invalid request tuple")
        rid, start, end, size, pref, flex = req
        if not isinstance(rid, str) or not rid:
            raise ValueError("Invalid request id")
        if rid in request_ids:
            raise ValueError("Duplicate request id")
        request_ids.add(rid)
        if not isinstance(start, int) or not isinstance(end, int) or start >= end or not (0 <= start < end <= 10**9):
            raise ValueError("Invalid start/end")
        if not isinstance(size, int) or not (1 <= size <= 1000):
            raise ValueError("Invalid size")
        if pref is not None:
            if not isinstance(pref, str):
                raise ValueError("Invalid pref")
            if pref not in room_names:
                raise ValueError("Unknown pref")
        if not isinstance(flex, int) or not (0 <= flex <= 10**9):
            raise ValueError("Invalid flex")

    bookings = {name: [] for name in room_names}
    assign = []
    busy = {name: 0 for name in room_names}

    for rid, start, end, size, pref, flex in requests:
        eligible = [(name, info) for name, info in room_info.items() if info[0] >= size]
        if not eligible:
            assign.append(None)
            continue

        all_valid_intervals = []
        for name, (cap, gap, idx) in eligible:
            forbidden = []
            for bs, be in bookings[name]:
                L = bs - end - gap + 1
                R = be - start - 1
                if L <= R:
                    fL = max(0, L)
                    fR = min(flex, R)
                    if fL <= fR:
                        forbidden.append((fL, fR))

            if forbidden:
                forbidden.sort()
                merged = [forbidden[0]]
                for a, b in forbidden[1:]:
                    if a <= merged[-1][1] + 1:
                        merged[-1] = (merged[-1][0], max(merged[-1][1], b))
                    else:
                        merged.append((a, b))
            else:
                merged = []

            valid = []
            curr = 0
            for a, b in merged:
                if a > curr:
                    valid.append((curr, a - 1))
                curr = max(curr, b + 1)
            if curr <= flex:
                valid.append((curr, flex))

            all_valid_intervals.extend(valid)

        if not all_valid_intervals:
            assign.append(None)
            continue

        all_valid_intervals.sort()
        merged_valid = []
        for a, b in all_valid_intervals:
            if merged_valid and a <= merged_valid[-1][1] + 1:
                merged_valid[-1] = (merged_valid[-1][0], max(merged_valid[-1][1], b))
            else:
                merged_valid.append((a, b))

