def _validate_leaps(leaps):
    if not isinstance(leaps, (list, tuple)):
        raise ValueError("leaps must be a list or tuple")
    if len(leaps) > 200:
        raise ValueError("leaps has more than 200 entries")

    prev_year, prev_month = 0, 0
    leaps_map = {}

    for entry in leaps:
        if not isinstance(entry, (list, tuple)):
            raise ValueError("Each entry in leaps must be a list or tuple")
        if len(entry) != 3:
            raise ValueError("Each entry must have exactly 3 elements")

        year, month, delta = entry

        # Check types: must be int, not bool
        if isinstance(year, bool) or isinstance(month, bool) or isinstance(delta, bool):
            raise ValueError("Components must be integers, not booleans")
        if not isinstance(year, int) or not isinstance(month, int) or not isinstance(delta, int):
            raise ValueError("Components must be integers")

        if not (1970 <= year <= 9998):
            raise ValueError(f"Year {year} out of range")
        if not (1 <= month <= 12):
            raise ValueError(f"Month {month} out of range")
        if delta not in (1, -1):
            raise ValueError(f"Delta must be 1 or -1, got {delta}")

        # Strictly increasing order
        if (year, month) <= (prev_year, prev_month):
            raise ValueError("Leap entries must be in strictly increasing order")
        prev_year, prev_month = year, month

        if year not in leaps_map:
            leaps_map[year] = {}
        leaps_map[year][month] = delta

    return leaps_map

def _is_leap_year(y):
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

def _days_in_month(y, m):
    if m in (1, 3, 5, 7, 8, 10, 12):
        return 31
    elif m in (4, 6, 9, 11):
        return 30
    elif m == 2:
        return 29 if _is_leap_year(y) else 28

def leap_label(n, leaps):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 0:
        raise ValueError("n must be >= 0")

    leaps_map = _validate_leaps(leaps)

    y = 1970
    while True:
        if y > 9999:
            raise ValueError("Year exceeds 9999")

        days = 366 if _is_leap_year(y) else 365
        base_seconds = days * 86400
        adj = 0
        if y in leaps_map:
            for d in leaps_map[y].values():
                adj += d
        total_seconds = base_seconds + adj

        if n >= total_seconds:
            n -= total_seconds
            y += 1
        else:
            break

    m = 1
    while m <= 12:
        days = _days_in_month(y, m)
        base_seconds = days * 86400
        adj = 0
        if y in leaps_map and m in leaps_map[y]:
            adj = leaps_map[y][m]
        total_seconds = base_seconds + adj

        if n >= total_seconds:
            n -= total_seconds
            m += 1
        else:
            break

    days_in_m = _days_in_month(y, m)
    is_leap_day = (y in leaps_map and m in leaps_map[y])
    leap_delta = leaps_map[y][m] if is_leap_day else 0

    if is_leap_day:
        # Last day is special
        threshold = (days_in_m - 1) * 86400
        if n >= threshold:
            n -= threshold
            d = days_in_m
            # n is seconds into the leap day (0 to 86400+delta-1)
            # Handle 23:59:60 case
            if leap_delta == 1 and n == 86400:
                return f"{y:04d}-{m:02d}-{d:02d} 23:59:60"
            # Otherwise normal calculation
        else:
            d = n // 86400 + 1
            n %= 86400
    else:
        d = n // 86400 + 1
        n %= 86400

    h = n // 3600
    m_rem = n % 3600
    mi = m_rem // 60
    s = m_rem % 60

    return f"{y:04d}-{m:02d}-{d:02d} {h:02d}:{mi:02d}:{s:02d}"

def leap_count(label, leaps):
    if not isinstance(label, str):
        raise ValueError("label must be a string")
    if len(label) != 19:
        raise ValueError("label must be exactly 19 characters")

    # Validate format strictly
    # YYYY-MM-DD hh:mm:ss
    if label[4] != '-' or label[7] != '-' or label[10] != ' ' or label[13] != ':' or label[16] != ':':
        raise ValueError("Invalid format")

    try:
        y = int(label[0:4])
        m = int(label[5:7])
        d = int(label[8:10])
        h = int(label[11:13])
        mi = int(label[14:16])
        s = int(label[17:19])
    except ValueError:
        raise ValueError("Non-digit characters found")

    # Check if digits only (already handled by int conversion but check range)
    # Also ensure no other chars
    if label.replace('-', '').replace(' ', '').replace(':', '').isdigit() == False:
        # Actually int conversion handles digits, but let's be safe
        pass

    if not (1970 <= y <= 9999):
        raise ValueError("Year out of range")
    if not (1 <= m <= 12):
        raise ValueError("Month out of range")
    if not (1 <= d <= 31): # Basic check, refined later
        raise ValueError("Day out of range")
    if not (0 <= h <= 23):
        raise ValueError("Hour out of range")
    if not (0 <= mi <= 59):
        raise ValueError("Minute out of range")
    if not (0 <= s <= 60):
        raise ValueError("Second out of range")

    # Validate day
    dim = _days_in_month(y, m)
    if d > dim:
        raise ValueError("Day out of range for month")

