    leaps_map = _validate_leaps(leaps)
    is_leap_day = (y in leaps_map and m in leaps_map[y])
    leap_delta = leaps_map[y][m] if is_leap_day else 0

    if s == 60:
        if not (h == 23 and mi == 59):
            raise ValueError("23:59:60 only allowed at end of day")
        if not is_leap_day or leap_delta != 1:
            raise ValueError("23:59:60 only allowed on +1 leap days")
    elif s == 59:
        if is_leap_day and leap_delta == -1:
            raise ValueError("23:59:59 does not exist on -1 leap days")
    else:
        if is_leap_day and leap_delta == -1:
            # On -1 day, seconds go 0..58. s=59 is invalid.
            # We already checked s=59 above.
            # But if s < 59, it's fine.
            pass

    # Calculate n
    n = 0

    # Add seconds for full years
    for yy in range(1970, y):
        days = 366 if _is_leap_year(yy) else 365
        base = days * 86400
        adj = 0
        if yy in leaps_map:
            for d_val in leaps_map[yy].values():
                adj += d_val
        n += base + adj

    # Add seconds for full months in current year
    for mm in range(1, m):
        days = _days_in_month(y, mm)
        base = days * 86400
        adj = 0
        if y in leaps_map and mm in leaps_map[y]:
            adj = leaps_map[y][mm]
        n += base + adj

    # Add seconds for full days in current month
    # Days 1 to d-1 are normal (86400)
    n += (d - 1) * 86400

    # Add seconds elapsed in current day
    # If it's a +1 leap day and time is 23:59:60, elapsed is 86400
    if is_leap_day and leap_delta == 1 and h == 23 and mi == 59 and s == 60:
        n += 86400
    else:
        n += h * 3600 + mi * 60 + s

    return n

