    # Add seconds for full months in current year
    for mm in range(1, m):
        days = _days_in_month(y, mm)
        base = days * 86400
        adj = 0
        if (y, mm) in leaps_map:
            adj = leaps_map[(y, mm)]
        n += base + adj

    # Add seconds for full days in current month
    # Days 1 to d-1 are normal (86400)
    n += (d - 1) * 86400

    # Add seconds elapsed in current day
    if s == 60:
        n += 86400
    else:
        n += h * 3600 + mi * 60 + s

    return n

