def _days_before(y):
    return 365*(y-1970) + (y-1970)//4 - (y-1970)//100 + (y-1970)//400

def _days_to_ymd(days):
    y = 1970 + days // 365
    while _days_before(y+1) <= days:
        y += 1
    while _days_before(y) > days:
        y -= 1
    days_in_year = days - _days_before(y)
    is_leap = (y%4==0 and y%100!=0) or (y%400==0)
    dim = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if is_leap:
        dim[2] = 29
    m = 1
    while days_in_year >= dim[m]:
        days_in_year -= dim[m]
        m += 1
    d = days_in_year + 1
    return y, m, d

