def _days_to_date(days):
    y = 1970
    while True:
        days_in_year = 366 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 365
        if days < days_in_year:
            break
        days -= days_in_year
        y += 1
    m = 1
    while True:
        if m in (1, 3, 5, 7, 8, 10, 12):
            dim = 31
        elif m in (4, 6, 9, 11):
            dim = 30
        else:
            dim = 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28
        if days < dim:
            break
        days -= dim
        m += 1
    d = days + 1
    return y, m, d

def _date_to_days(y, m, d):
    days = 0
    for yr in range(1970, y):
        days += 366 if (yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)) else 365
    for mo in range(1, m):
        if mo in (1, 3, 5, 7, 8, 10, 12):
            dim = 31
        elif mo in (4, 6, 9, 11):
            dim = 30
        else:
            dim = 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28
        days += dim
    days += d - 1
    return days

def _get_offset(y, m, leap_keys, cum_leaps):
    i = bisect.bisect_left(leap_keys, (y, m))
    return cum_leaps[i]

def _is_last_day(y, m, d):
    if m in (1, 3, 5, 7, 8, 10, 12):
        return d == 31
    elif m in (4, 6, 9, 11):
        return d == 30
    else:
        return d == 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28

def _days_in_month(y, m):
    if m in (1, 3, 5, 7, 8, 10, 12): return 31
    elif m in (4, 6, 9, 11): return 30
    else: return 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28

def leap_label(n, leaps):
