    y, m, d = _days_to_date(n // 86400)

    while True:
        off = _get_offset(y, m, leap_keys, cum_leaps)
        n_adj = n - off
        days_adj = n_adj // 86400
        y2, m2, d2 = _days_to_date(days_adj)
        if y2 == y and m2 == m and d2 == d:
            y, m, d = y2, m2, d2
            break
        y, m, d = y2, m2, d2

    if y > 9999:
        raise ValueError("Year exceeds 9999")

    time_s = n_adj % 86400
    h = time_s // 3600
    m_rem = (time_s % 3600) // 60
    s = time_s % 60

    return f"{y:04d}-{m:02d}-{d:02d} {h:02d}:{m_rem:02d}:{s:02d}"

