def list_schedule(jobs, workers):
    # Validate workers
    if not isinstance(workers, int) or isinstance(workers, bool):
        raise ValueError("workers must be an integer")
    if workers < 1 or workers > 64:
        raise ValueError("workers must be between 1 and 64")

    # Validate jobs structure
    if not isinstance(jobs, (list, tuple)):
        raise ValueError("jobs must be a list or tuple")

    job_map = {}
    names = set()

    # First pass: parse and basic validation
    for job_tuple in jobs:
        if not isinstance(job_tuple, tuple) or len(job_tuple) != 3:
            raise ValueError("Each job must be a tuple of (name, duration, deps)")

        name, duration, deps = job_tuple

        # Validate name
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("Job name must be a non-empty string")
        if name in names:
            raise ValueError("Job names must be unique")
        names.add(name)

        # Validate duration
        if not isinstance(duration, int) or isinstance(duration, bool):
            raise ValueError("Job duration must be an integer")
        if duration < 0 or duration > 10**12:
            raise ValueError("Job duration must be between 0 and 10^12")

        # Validate deps
        if not isinstance(deps, (list, tuple)):
            raise ValueError("Deps must be a list or tuple")
        for d in deps:
            if not isinstance(d, str):
                raise ValueError("Dependencies must be strings")

        job_map[name] = (duration, deps)

    # Validate deps content
    for name, (duration, deps) in job_map.items():
        for d in deps:
            if d not in names:
                raise ValueError(f"Unknown dependency '{d}' in job '{name}'")
            if d == name:
                raise ValueError(f"Job '{name}' cannot depend on itself")

        # Check for repeated deps
        if len(deps) != len(set(deps)):
            raise ValueError(f"Repeated dependencies in job '{name}'")

    # Build graph for cycle detection and priority
    # Edge u -> v exists if u is in v's deps (u must finish before v)
    # This is the direction of execution flow.
    # adj[u] = list of jobs that depend on u
    adj = {name: [] for name in names}
    in_degree = {name: 0 for name in names}

    for name, (duration, deps) in job_map.items():
        for d in deps:
            adj[d].append(name)
            in_degree[name] += 1

    # Cycle detection using Kahn's algorithm
    queue = [n for n in names if in_degree[n] == 0]
    visited_count = 0
    temp_in_degree = dict(in_degree)

    # We need a queue for BFS
    q = list(queue)
    idx = 0
    while idx < len(q):
        u = q[idx]
        idx += 1
        visited_count += 1
        for v in adj[u]:
            temp_in_degree[v] -= 1
            if temp_in_degree[v] == 0:
                q.append(v)

    if visited_count != len(names):
        raise ValueError("Dependency cycle detected")

    # Compute priorities
    # Priority of a job = max duration sum of any chain starting at job following adj edges
    # This is longest path in DAG starting at job.
    # Since it's a DAG, we can compute this using memoization or reverse topological order.
    # Let's use memoization.
    memo = {}

    def get_priority(node):
        if node in memo:
            return memo[node]

        dur = job_map[node][0]
        max_chain = 0
        for neighbor in adj[node]:
            max_chain = max(max_chain, get_priority(neighbor))

        memo[node] = dur + max_chain
        return memo[node]

    for name in names:
        get_priority(name)

    # Simulation
    start_times = {}
    worker_map = {}
    completed_jobs = set()

    # State for workers: list of (job_name, finish_time) or None
    worker_state = [None] * workers

    # Remaining dependencies count
    remaining_deps = {name: len(job_map[name][1]) for name in names}

    # Ready jobs list
    # We will maintain a list and sort it when needed or keep it sorted.
    # Given N <= 200, sorting is cheap.
    ready_jobs = [name for name in names if remaining_deps[name] == 0]

    # Helper to sort ready jobs
    def sort_ready_jobs():
        ready_jobs.sort(key=lambda x: (-memo[x], x))

    sort_ready_jobs()

    current_time = 0
    total_jobs = len(names)

    # If no jobs, return immediately
    if total_jobs == 0:
        return {"start": {}, "worker": {}, "makespan": 0}

    while len(completed_jobs) < total_jobs:
        # Phase 1: Complete jobs at current_time
        finished_this_step = []
        for w in range(workers):
            if worker_state[w] is not None:
                job_name, finish_time = worker_state[w]
                if finish_time == current_time:
                    finished_this_step.append((w, job_name))

        for w, job_name in finished_this_step:
            worker_state[w] = None
            completed_jobs.add(job_name)

            # Update dependencies
            for dep_job in adj[job_name]:
                remaining_deps[dep_job] -= 1
                if remaining_deps[dep_job] == 0:
                    ready_jobs.append(dep_job)

        # Phase 2: Schedule jobs
        # We need to repeatedly schedule jobs as long as there are idle workers and ready jobs.
        # This handles 0-duration jobs cascading.

        while True:
            # Find idle workers
            idle_workers = [w for w in range(workers) if worker_state[w] is None]
            if not idle_workers:
                break

            # Sort ready jobs to pick best
            sort_ready_jobs()

            if not ready_jobs:
                break

            # Pick best job
            job_name = ready_jobs.pop(0)

            # Pick lowest idle worker
            worker_idx = idle_workers[0]

            # Assign
            start_times[job_name] = current_time
            worker_map[job_name] = worker_idx
            duration = job_map[job_name][0]
            finish_time = current_time + duration

            if duration == 0:
                # Instant finish
                completed_jobs.add(job_name)
                # Worker state remains None (idle)
                # Update dependencies
                for dep_job in adj[job_name]:
                    remaining_deps[dep_job] -= 1
                    if remaining_deps[dep_job] == 0:
                        ready_jobs.append(dep_job)
                # Continue loop to process newly ready jobs
            else:
                # Busy until finish_time
                worker_state[worker_idx] = (job_name, finish_time)
                # Worker is now busy.
                # We can continue to check if other workers are idle.
                # But we must not pick this worker again.
                # The loop will recompute idle_workers, so it's safe.
                pass

        # Phase 3: Advance time
        if len(completed_jobs) == total_jobs:
            break

        # Find earliest finish time of running jobs
        running_finish_times = []
        for w in range(workers):
            if worker_state[w] is not None:
                running_finish_times.append(worker_state[w][1])

        if not running_finish_times:
            # No running jobs, but not done?
            # This implies deadlock or error, but we checked cycles.
            # Or maybe ready_jobs is not empty but no workers?
            # But we just ran the scheduling loop which fills idle workers.
            # So if no running jobs, all workers are idle.
            # If all workers idle and not done, then ready_jobs must be empty?
            # If ready_jobs empty and no running jobs -> deadlock.
