        calc_priority(j)

    # --- Simulation ---
    if not names:
        return {"start": {}, "worker": {}, "makespan": 0}

    remaining_deps = {j: len(job_data[j][1]) for j in names}
    ready_jobs = [j for j in names if remaining_deps[j] == 0]
    running = {}  # worker -> (job_name, finish_time)
    start_times = {}
    worker_map = {}
    time = 0

    while len(start_times) < len(names):
        # Finish jobs that complete at current time
        finish_now = [(w, j) for w, (j, ft) in running.items() if ft == time]
        for w, j in finish_now:
            del running[w]
            for dep in forward_deps[j]:
                remaining_deps[dep] -= 1
                if remaining_deps[dep] == 0:
                    ready_jobs.append(dep)

        # Sort ready jobs by priority (desc), then name (asc)
        ready_jobs.sort(key=lambda j: (-priority[j], j))

        # Assign ready jobs to lowest-numbered idle workers
        idle_workers = sorted(set(range(workers)) - set(running.keys()))
        while ready_jobs and idle_workers:
            j = ready_jobs.pop(0)
            w = idle_workers.pop(0)
            dur = job_data[j][0]

            start_times[j] = time
            worker_map[j] = w

            if dur == 0:
                # Zero-duration jobs finish immediately, freeing the worker instantly
                for dep in forward_deps[j]:
                    remaining_deps[dep] -= 1
                    if remaining_deps[dep] == 0:
                        ready_jobs.append(dep)
                # Re-sort to account for newly ready jobs at the same time instant
                ready_jobs.sort(key=lambda j: (-priority[j], j))
                # Worker remains idle, idle_workers list is unchanged
            else:
                running[w] = (j, time + dur)
                # Recalculate idle workers since one is now busy
                idle_workers = sorted(set(range(workers)) - set(running.keys()))

        # Advance time to next event
        if running:
            time = min(ft for _, ft in running.values())
        else:
            # Should not be reachable for valid DAG inputs
            break

    makespan = max(start_times[j] + job_data[j][0] for j in start_times)
    return {"start": start_times, "worker": worker_map, "makespan": makespan}

def two_square_reps(n):
    # Input validation
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an int")
    if n < 0 or n > 10**12:
        raise ValueError("n must be between 0 and 10**12")

    # Special case for 0
    if n == 0:
        return (1, [(0, 0)])

    # Factorization
    factors = {}
    temp = n
    d = 2
    while d * d <= temp and d <= 1000000:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            factors[d] = count
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Check for primes 3 mod 4 with odd exponent
    for p, exp in factors.items():
        if p % 4 == 3 and exp % 2 != 0:
            return (0, [])

    # Calculate r
    r = 4
    for p, exp in factors.items():
        if p % 4 == 1:
            r *= (exp + 1)

    # Find representations
    # We will generate Gaussian integers z such that z * conj(z) = n
    # Then extract pairs (|Re(z)|, |Im(z)|)

    candidates = [1+0j]

    # Handle factor 2
    if 2 in factors:
        k = factors[2]
        # (1+i) has norm 2. We need to multiply by (1+i)^k
        # But wait, 2 = -i(1+i)^2. So (1+i)^2 is associate of 2.
        # Actually, simpler: just multiply by (1+i)^k
        val = (1+1j)**k
        new_candidates = []
        for z in candidates:
            new_candidates.append(z * val)
        candidates = new_candidates

    # Handle primes 3 mod 4
    # q^2f has representation (q^f, 0). In Gaussian integers, this is just q^f (real)
    for p, exp in factors.items():
        if p % 4 == 3:
            f = exp // 2
            val = complex(p**f, 0)
            new_candidates = []
            for z in candidates:
                new_candidates.append(z * val)
            candidates = new_candidates

    # Handle primes 1 mod 4
    for p, exp in factors.items():
        if p % 4 == 1:
            # Find a, b such that a^2 + b^2 = p
            # Since p can be large, we search. p <= 10^12, sqrt(p) <= 10^6.
            # This search is acceptable.
            a = 1
            found = False
            while a * a <= p // 2:
                b2 = p - a * a
                b = int(b2**0.5)
                if b * b == b2:
                    found = True
                    break
                a += 1
            if not found:
                # Should not happen for prime 1 mod 4
                continue

            pi = complex(a, b)
            pi_bar = complex(a, -b)

            # Factors are pi^u * pi_bar^(exp-u) for u in 0..exp
            # We can generate these powers iteratively
            powers = []
            curr_pi = 1+0j
            curr_pi_bar = 1+0j
            for u in range(exp + 1):
                powers.append(curr_pi * curr_pi_bar)
                curr_pi *= pi
                curr_pi_bar *= pi_bar

            new_candidates = []
            for z in candidates:
                for pwr in powers:
                    new_candidates.append(z * pwr)
            candidates = new_candidates

    # Extract pairs
    pairs_set = set()
    for z in candidates:
        x = int(z.real)
        y = int(z.imag)
        a, b = abs(x), abs(y)
        if a < b:
            a, b = b, a
        pairs_set.add((a, b))

    pairs = sorted(list(pairs_set))

    return (r, pairs)

import sys

def capped_part_count(n, parts, m):
    # Strict validation
    if type(n) is not int or n < 0 or n > 10**18:
        raise ValueError("n must be an int in 0..10**18")
    if type(m) is not int or m < 1 or m > 10**18:
        raise ValueError("m must be an int in 1..10**18")
    if type(parts) not in (list, tuple):
        raise ValueError("parts must be a list or tuple")
    if not (1 <= len(parts) <= 6):
        raise ValueError("parts must have between 1 and 6 elements")

    sizes = []
    caps = []

    for pair in parts:
        if type(pair) not in (list, tuple) or len(pair) != 2:
            raise ValueError("each part must be a 2-sequence")
        s, c = pair
        if type(s) is not int or s < 1 or s > 12:
            raise ValueError("size must be an int in 1..12")
        if c is not None and (type(c) is not int or c < 0 or c > 9):
            raise ValueError("cap must be None or an int in 0..9")
        if s in sizes:
            raise ValueError("sizes must be distinct")
        sizes.append(s)
        caps.append(c)

    if m == 1:
        return 0
    if n == 0:
        return 1 % m

    finite_parts = []
    infinite_sizes = []

    for s, c in zip(sizes, caps):
        if c is None:
            infinite_sizes.append(s)
        else:
            finite_parts.append((s, c))

    # Compute Q(x) = product of finite parts polynomials
    q_coeffs = [1]
    max_deg_q = 0

    for s, c in finite_parts:
        new_max_deg = max_deg_q + c * s
        new_q = [0] * (new_max_deg + 1)
        for j in range(c + 1):
            shift = j * s
            for i in range(len(q_coeffs)):
                new_q[i + shift] += q_coeffs[i]
        for i in range(len(new_q)):
            new_q[i] %= m
        q_coeffs = new_q
        max_deg_q = new_max_deg

    if not infinite_sizes:
        if n > max_deg_q:
            return 0
        else:
            return q_coeffs[n] % m

    # Compute D(x) = product (1 - x^s) for infinite parts
    d_coeffs = [1]
    max_deg_d = 0

    for s in infinite_sizes:
        new_max_deg = max_deg_d + s
        new_d = [0] * (new_max_deg + 1)
        for i in range(len(d_coeffs)):
            new_d[i] = (new_d[i] + d_coeffs[i]) % m
            if i + s <= new_max_deg:
                new_d[i + s] = (new_d[i + s] - d_coeffs[i]) % m
        d_coeffs = new_d
        max_deg_d = new_max_deg

    S = max_deg_d

    # Compute p_0 ... p_{max_deg_q} using recurrence
    limit = max_deg_q
    p = [0] * (limit + 1)
    p[0] = 1 % m

    for i in range(1, limit + 1):
        qi = q_coeffs[i] if i <= max_deg_q else 0
        sum_term = 0
        for k in range(1, S + 1):
            if i - k >= 0:
                sum_term = (sum_term + d_coeffs[k] * p[i - k]) % m
            else:
                break
        p[i] = (qi - sum_term) % m

    if n <= limit:
        return p[n] % m

    # Matrix exponentiation for n > limit
    # State vector V_i = [p_i, p_{i-1}, ..., p_{i-S+1}]^T
    V = [0] * S
    for j in range(S):
        idx = limit - j
        V[j] = p[idx] if idx >= 0 else 0

    # Transition matrix M
    M = [[0] * S for _ in range(S)]
    for j in range(S):
        M[0][j] = (-d_coeffs[j + 1]) % m
    for i in range(1, S):
        M[i][i - 1] = 1

    steps = n - limit

    def mat_mul(A, B):
        C = [[0] * S for _ in range(S)]
        for i in range(S):
            for k in range(S):
                if A[i][k] == 0: continue
                val = A[i][k]
                for j in range(S):
                    C[i][j] = (C[i][j] + val * B[k][j]) % m
        return C

    def mat_pow(A, p):
        res = [[0] * S for _ in range(S)]
        for i in range(S): res[i][i] = 1
        base = A
        while p > 0:
            if p % 2 == 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            p //= 2
        return res

    M_n = mat_pow(M, steps)

    res = 0
    for j in range(S):
        res = (res + M_n[0][j] * V[j]) % m

    return res

def union_stats(rects):
    if not isinstance(rects, (list, tuple)):
        raise ValueError("Input must be a list or tuple")

    valid_rects = []
    for r in rects:
        if not isinstance(r, (list, tuple)) or len(r) != 4:
            raise ValueError("Each rectangle must be a list/tuple of 4 elements")
        x1, y1, x2, y2 = r
        if not (type(x1) is int and type(y1) is int and type(x2) is int and type(y2) is int):
            raise ValueError("Coordinates must be integers (not booleans)")
        if x1 > x2 or y1 > y2:
            raise ValueError("x1 <= x2 and y1 <= y2 required")
        valid_rects.append((x1, y1, x2, y2))

    non_degenerate = [r for r in valid_rects if r[0] != r[2] and r[1] != r[3]]
    if not non_degenerate:
        return (0, 0, 0)

    xs = sorted(set(x for r in non_degenerate for x in (r[0], r[2])))
    ys = sorted(set(y for r in non_degenerate for y in (r[1], r[3])))

    K = len(xs)
    L = len(ys)
    covered = [[False] * (L - 1) for _ in range(K - 1)]

    for i in range(K - 1):
        for j in range(L - 1):
            for x1, y1, x2, y2 in non_degenerate:
                if x1 <= xs[i] and x2 >= xs[i+1] and y1 <= ys[j] and y2 >= ys[j+1]:
                    covered[i][j] = True
                    break

    area = 0
    for i in range(K - 1):
        for j in range(L - 1):
            if covered[i][j]:
                area += (xs[i+1] - xs[i]) * (ys[j+1] - ys[j])

    perimeter = 0
    for i in range(K - 1):
        for j in range(L - 1):
            if covered[i][j]:
                if i == 0 or not covered[i-1][j]:
                    perimeter += ys[j+1] - ys[j]
                if i == K - 2 or not covered[i+1][j]:
                    perimeter += ys[j+1] - ys[j]
                if j == 0 or not covered[i][j-1]:
                    perimeter += xs[i+1] - xs[i]
                if j == L - 2 or not covered[i][j+1]:
                    perimeter += xs[i+1] - xs[i]

    M = len(non_degenerate)
    parent = list(range(M))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj

    for i in range(M):
        for j in range(i + 1, M):
            r1 = non_degenerate[i]
            r2 = non_degenerate[j]
            ix1 = max(r1[0], r2[0])
            ix2 = min(r1[2], r2[2])
            iy1 = max(r1[1], r2[1])
            iy2 = min(r1[3], r2[3])

            if ix1 <= ix2 and iy1 <= iy2:
                if ix2 > ix1 or iy2 > iy1:
                    union(i, j)

    components = len(set(find(i) for i in range(M)))

    return (area, perimeter, components)

def union_stats(rects):
    # Validate input type
    if not isinstance(rects, (list, tuple)):
