        # type(x) is int ensures bool is rejected since bool is a subclass of int
        if not (type(x1) is int and type(y1) is int and type(x2) is int and type(y2) is int):
            raise ValueError("Coordinates must be integers (not booleans)")

        # Validate coordinate range
        if not (-10**9 <= x1 <= 10**9 and -10**9 <= y1 <= 10**9 and 
                -10**9 <= x2 <= 10**9 and -10**9 <= y2 <= 10**9):
            raise ValueError("Coordinates must be within [-10^9, 10^9]")

        # Validate ordering
        if x1 > x2 or y1 > y2:
            raise ValueError("x1 <= x2 and y1 <= y2 required")

        valid_rects.append((x1, y1, x2, y2))

    # Filter out degenerate rectangles (area 0)
    # A rectangle is degenerate if x1 == x2 or y1 == y2
    non_degenerate = [r for r in valid_rects if r[0] != r[2] and r[1] != r[3]]

    if not non_degenerate:
        return (0, 0, 0)

    # Coordinate compression
    xs = sorted(set(x for r in non_degenerate for x in (r[0], r[2])))
    ys = sorted(set(y for r in non_degenerate for y in (r[1], r[3])))

    # Map coordinates to indices for grid
    x_map = {x: i for i, x in enumerate(xs)}
    y_map = {y: i for i, y in enumerate(ys)}

    K = len(xs)
    L = len(ys)

    # Grid to store coverage of elementary rectangles
    # covered[i][j] is True if the region [xs[i], xs[i+1]] x [ys[j], ys[j+1]] is covered
    covered = [[False] * (L - 1) for _ in range(K - 1)]

    for i in range(K - 1):
        for j in range(L - 1):
            # Check if any rectangle covers this cell
            # A rectangle covers the cell if it spans over the entire cell interval
            for r in non_degenerate:
                rx1, ry1, rx2, ry2 = r
                if rx1 <= xs[i] and rx2 >= xs[i+1] and ry1 <= ys[j] and ry2 >= ys[j+1]:
                    covered[i][j] = True
                    break

    # Calculate Area
    area = 0
    for i in range(K - 1):
        for j in range(L - 1):
            if covered[i][j]:
                area += (xs[i+1] - xs[i]) * (ys[j+1] - ys[j])

    # Calculate Perimeter
    perimeter = 0
    for i in range(K - 1):
        for j in range(L - 1):
            if covered[i][j]:
                # Check boundaries of the cell
                # Left edge (x = xs[i])
                if i == 0 or not covered[i-1][j]:
                    perimeter += ys[j+1] - ys[j]
                # Right edge (x = xs[i+1])
                if i == K - 2 or not covered[i+1][j]:
                    perimeter += ys[j+1] - ys[j]
                # Bottom edge (y = ys[j])
                if j == 0 or not covered[i][j-1]:
                    perimeter += xs[i+1] - xs[i]
                # Top edge (y = ys[j+1])
                if j == L - 2 or not covered[i][j+1]:
                    perimeter += xs[i+1] - xs[i]

    # Calculate Components using Union-Find
    M = len(non_degenerate)
    parent = list(range(M))

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj

    # Check connectivity between all pairs
    for i in range(M):
        for j in range(i + 1, M):
            r1 = non_degenerate[i]
            r2 = non_degenerate[j]

            # Intersection interval
            ix1 = max(r1[0], r2[0])
            ix2 = min(r1[2], r2[2])
            iy1 = max(r1[1], r2[1])
            iy2 = min(r1[3], r2[3])

            # Check if intersection is non-empty and not a single point
            # Non-empty: ix1 <= ix2 and iy1 <= iy2
            # Not a single point: width > 0 or height > 0 (since integers, width >= 1 or height >= 1)
            # Wait, intersection of [0, 2] and [2, 4] is [2, 2], width 0.
            # Intersection of [0, 2] and [1, 3] is [1, 2], width 1.
            # So condition is: (ix1 <= ix2) and (iy1 <= iy2) and ((ix2 > ix1) or (iy2 > iy1))

            if ix1 <= ix2 and iy1 <= iy2:
                if ix2 > ix1 or iy2 > iy1:
                    union(i, j)

    components = len(set(find(i) for i in range(M)))

    return (area, perimeter, components)

