        if not isinstance(r, (list, tuple)) or len(r) != 4:
            raise ValueError("Each rectangle must be a list or tuple of 4 elements")
        x1, y1, x2, y2 = r
        for val in (x1, y1, x2, y2):
            if type(val) is not int:
                raise ValueError("Rectangle values must be ints")
            if abs(val) > 10**9:
                raise ValueError("Rectangle values out of range")
        if x1 > x2 or y1 > y2:
            raise ValueError("x1 <= x2 and y1 <= y2 required")
        if x1 == x2 or y1 == y2:
            continue
        valid_rects.append((x1, y1, x2, y2))

    if not valid_rects:
        return 0, 0, 0

    # Components calculation using Union-Find
    n = len(valid_rects)
    parent = list(range(n))
    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i
    def union(i, j):
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj

    for i in range(n):
        for j in range(i + 1, n):
            r1 = valid_rects[i]
            r2 = valid_rects[j]
            # Check if they overlap or share a boundary segment of positive length
            # Intersection x-range: [max(x1), min(x2)]
            # Intersection y-range: [max(y1), min(y2)]
            overlap_x = min(r1[2], r2[2]) - max(r1[0], r2[0])
            overlap_y = min(r1[3], r2[3]) - max(r1[1], r2[1])

            # If overlap is non-negative in both dimensions, they intersect.
            # We need the intersection to be more than a single point.
            # A point intersection happens if overlap_x == 0 and overlap_y == 0.
            if overlap_x >= 0 and overlap_y >= 0 and (overlap_x > 0 or overlap_y > 0):
                union(i, j)

    components = len(set(find(i) for i in range(n)))

    # Area & Perimeter via coordinate compression
    xs = sorted(set(x for r in valid_rects for x in (r[0], r[2])))
    ys = sorted(set(y for r in valid_rects for y in (r[1], r[3])))

    # Map coordinates to indices for fast lookup
    x_map = {x: i for i, x in enumerate(xs)}
    y_map = {y: i for i, y in enumerate(ys)}

    nx = len(xs) - 1
    ny = len(ys) - 1

    # Grid to track coverage. Dimensions nx x ny.
    # covered[i][j] is True if the cell [xs[i], xs[i+1]] x [ys[j], ys[j+1]] is covered.
    covered = [[False] * ny for _ in range(nx)]

    # Mark covered cells
    for r in valid_rects:
        x1, y1, x2, y2 = r
        # Find indices in xs and ys
        # Since x1, x2 are in xs, we can use the map
        ix1 = x_map[x1]
        ix2 = x_map[x2]
        iy1 = y_map[y1]
        iy2 = y_map[y2]

        # Mark the rectangle in the grid
        # The rectangle covers columns ix1 to ix2-1 and rows iy1 to iy2-1
        for i in range(ix1, ix2):
            for j in range(iy1, iy2):
                covered[i][j] = True

    area = 0
    perimeter = 0

    for i in range(nx):
        dx = xs[i+1] - xs[i]
        for j in range(ny):
            dy = ys[j+1] - ys[j]
            if not covered[i][j]:
                continue

            area += dx * dy

            # Check boundaries
            # Top edge (j+1)
            if j == ny - 1 or not covered[i][j+1]:
                perimeter += dx
            # Bottom edge (j-1)
            if j == 0 or not covered[i][j-1]:
                perimeter += dx
            # Left edge (i-1)
            if i == 0 or not covered[i-1][j]:
                perimeter += dy
            # Right edge (i+1)
            if i == nx - 1 or not covered[i+1][j]:
                perimeter += dy

    return area, perimeter, components

