def matrix_det_int(M):
    n = len(M)
    M = [row[:] for row in M]
    sign = 1
    prev_pivot = 1
    for i in range(n):
        if M[i][i] == 0:
            pivot = i + 1
            while pivot < n and M[pivot][i] == 0:
                pivot += 1
            if pivot == n:
                return 0
            M[i], M[pivot] = M[pivot], M[i]
            sign = -sign

        for j in range(i+1, n):
            if M[j][i] != 0:
                for k in range(i+1, n):
                    M[j][k] = (M[j][k] * M[i][i] - M[j][i] * M[i][k]) // prev_pivot
                M[j][i] = 0
        prev_pivot = M[i][i]

    return sign * M[n-1][n-1]

