def matrix_det_int(M):
    # Compute determinant of integer matrix M using Gaussian elimination with fractions
    # to ensure exactness, then convert to int.
    # Alternatively, use Bareiss algorithm. Here we use a robust integer determinant method.
    # Since N is small (<= 60), we can use a simple recursive expansion if N is very small,
    # but for N up to 60, O(N^3) is needed.
    # We will implement Gaussian elimination with rational arithmetic using fractions.Fraction
    # to avoid precision issues, then return the integer result.

    from fractions import Fraction

    n = len(M)
    if n == 0:
        return 1
    if n == 1:
        return int(M[0][0])

    # Convert to Fraction matrix
    mat = [[Fraction(x) for x in row] for row in M]

    det = Fraction(1)

    for i in range(n):
        # Find pivot
        pivot = i
        while pivot < n and mat[pivot][i] == 0:
            pivot += 1

        if pivot == n:
            return 0

        if pivot != i:
            mat[i], mat[pivot] = mat[pivot], mat[i]
            det = -det

        det *= mat[i][i]

        # Normalize row i? No, just eliminate
        # To keep numbers small, we can divide row i by mat[i][i]
        # But that changes determinant.
        # Better: eliminate column i using row i

        inv_pivot = Fraction(1, mat[i][i])

        for j in range(i + 1, n):
            if mat[j][i] != 0:
                factor = mat[j][i] * inv_pivot
                # Subtract factor * row i from row j
                # We can update the row directly
                for k in range(i, n):
                    mat[j][k] -= factor * mat[i][k]
                mat[j][i] = Fraction(0)

    return int(det)

