    # Input validation
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if not isinstance(queries, (list, tuple)):
        raise ValueError("queries must be a list or tuple")

    n = len(s)
    if n == 0:
        # If s is empty, queries must be empty or valid? 
        # Constraints say 1..400 chars, so s is not empty.
        pass

    # Validate queries
    for q in queries:
        if not isinstance(q, (list, tuple)):
            raise ValueError("Each query must be a list or tuple")
        if len(q) != 2:
            raise ValueError("Each query must have exactly two elements")
        l, r = q
        if not isinstance(l, int) or isinstance(l, bool):
            raise ValueError("Query indices must be ints")
        if not isinstance(r, int) or isinstance(r, bool):
            raise ValueError("Query indices must be ints")
        if l < 0 or r >= n or l > r:
            raise ValueError("Query indices out of bounds or invalid range")

    # Precompute palindrome table
    # is_pal[i][j] is True if s[i..j] is a palindrome
    is_pal = [[False] * n for _ in range(n)]
    for i in range(n):
        is_pal[i][i] = True
    for i in range(n - 1):
        is_pal[i][i + 1] = (s[i] == s[i + 1])

    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            is_pal[i][j] = (s[i] == s[j]) and is_pal[i + 1][j - 1]

    # DP table to store best palindrome for each range [l, r]
    # best[l][r] stores a tuple (start_index, length)
    # We use a list of lists for DP table
    # best[l][r] corresponds to range starting at l with length (r - l + 1)
    # To save space and time, we can use a 2D array where index is (l, r)
    # But since we iterate by length, we can just store in a 2D array.

    # best[l][r] will store (start, length)
    # Initialize with None
    best = [[None] * n for _ in range(n)]

    # Fill DP table by increasing length
    for length in range(1, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1

            # Candidates for best palindrome in s[l..r]
            candidates = []

            # 1. The whole substring s[l..r] if it is a palindrome
            if is_pal[l][r]:
                candidates.append((l, length))

            # 2. Best palindrome in s[l+1..r]
            if l + 1 <= r:
                cand2 = best[l + 1][r]
                if cand2 is not None:
                    candidates.append(cand2)

            # 3. Best palindrome in s[l..r-1]
            if l <= r - 1:
                cand3 = best[l][r - 1]
                if cand3 is not None:
                    candidates.append(cand3)

            # Select the best candidate
            # Criteria:
            # 1. Longest length
            # 2. Lexicographically smallest string
            # 3. Smallest start index

            best_candidate = None
            for cand in candidates:
                c_start, c_len = cand
                if best_candidate is None:
                    best_candidate = cand
                else:
                    b_start, b_len = best_candidate

                    # Compare lengths
                    if c_len > b_len:
                        best_candidate = cand
                    elif c_len == b_len:
                        # Compare strings
                        # s[c_start : c_start+c_len] vs s[b_start : b_start+b_len]
                        # Since lengths are equal, we can compare slices
                        # Optimization: compare directly
                        sub_c = s[c_start : c_start + c_len]
                        sub_b = s[b_start : b_start + c_len]
                        if sub_c < sub_b:
                            best_candidate = cand
                        elif sub_c == sub_b:
                            # Compare start indices
                            if c_start < b_start:
                                best_candidate = cand

            best[l][r] = best_candidate

    # Answer queries
    results = []
    for q in queries:
        l, r = q
        start, length = best[l][r]
        results.append((s[start : start + length], start))

    return results

def best_palindromes(s, queries):
    # Input validation
    if not isinstance(s, str):
        raise ValueError("s must be a string")

    n = len(s)
    if not (1 <= n <= 400):
        raise ValueError("s must have length between 1 and 400")

    if not isinstance(queries, (list, tuple)):
        raise ValueError("queries must be a list or tuple")

    for q in queries:
        if not isinstance(q, (list, tuple)):
            raise ValueError("Each query must be a list or tuple")
        if len(q) != 2:
            raise ValueError("Each query must have exactly two elements")
        l, r = q
        if isinstance(l, bool) or not isinstance(l, int):
            raise ValueError("Query indices must be ints")
        if isinstance(r, bool) or not isinstance(r, int):
            raise ValueError("Query indices must be ints")
        if l < 0 or r >= n or l > r:
            raise ValueError("Query indices out of bounds or invalid range")

    # Precompute palindrome table
    # is_pal[i][j] is True if s[i..j] is a palindrome
    is_pal = [[False] * n for _ in range(n)]

    for i in range(n):
        is_pal[i][i] = True
    for i in range(n - 1):
        is_pal[i][i + 1] = (s[i] == s[i + 1])

    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            is_pal[i][j] = (s[i] == s[j]) and is_pal[i + 1][j - 1]

    # best[l][r] stores a tuple (start_index, length) of the best palindrome in s[l..r]
    best = [[None] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1

            candidates = []
            if is_pal[l][r]:
                candidates.append((l, length))

            if l + 1 <= r:
                cand2 = best[l + 1][r]
                if cand2 is not None:
                    candidates.append(cand2)

            if l <= r - 1:
                cand3 = best[l][r - 1]
                if cand3 is not None:
                    candidates.append(cand3)

            best_candidate = None
            for cand in candidates:
                c_start, c_len = cand
                if best_candidate is None:
                    best_candidate = cand
                else:
                    b_start, b_len = best_candidate

                    if c_len > b_len:
                        best_candidate = cand
                    elif c_len == b_len:
                        # Compare strings lexicographically
                        # We can compare slices directly. 
                        # Optimization: compare character by character to avoid slicing if possible,
                        # but slicing is fast enough for N=400.
                        # To be safe and efficient, we compare without creating new strings if possible?
                        # Actually, Python's string comparison is very fast.
                        # But creating slices creates objects.
                        # Let's compare using indices.

                        # Compare s[c_start : c_start + c_len] vs s[b_start : b_start + b_len]
                        # Since lengths are equal, we can iterate.
                        # However, direct slice comparison is optimized in C.
                        # Let's stick to slice comparison for correctness and simplicity.
                        # But wait, if we have many candidates, creating slices is costly.
                        # But here candidates list size is at most 3. So it's fine.

                        sub_c = s[c_start : c_start + c_len]
                        sub_b = s[b_start : b_start + b_len]

                        if sub_c < sub_b:
                            best_candidate = cand
                        elif sub_c == sub_b:
                            if c_start < b_start:
                                best_candidate = cand

            best[l][r] = best_candidate

    # Answer queries
    results = []
    for q in queries:
        l, r = q
        start, length = best[l][r]
        results.append((s[start : start + length], start))

    return results

def maximal_runs(s: str) -> list:
    n = len(s)
    if n > 300:
        raise ValueError("String length exceeds 300")

    # Precompute LCP table
    # lcp[i][j] stores the length of the longest common prefix of s[i:] and s[j:]
    lcp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            lcp[i][j] = (1 if s[i] == s[j] else 0) + lcp[i + 1][j + 1]

    runs = []

    # Iterate over all possible periods
    for p in range(1, n // 2 + 1):
        start = 0
        # Iterate through the string to find maximal match segments for period p
        for k in range(n - p):
            if s[k] == s[k + p]:
                continue
            else:
                if k > start:
                    i, j = start, k + p
                    if j - i >= 2 * p:
                        # Check if p is the smallest period
                        is_smallest = True
                        for p_prime in range(1, p):
                            # Check if s[i:j] has period p_prime
                            # Condition: len(t) - p_prime <= lcp[i][i + p_prime]
                            if (j - i - p_prime) <= lcp[i][i + p_prime]:
                                is_smallest = False
                                break
                        if is_smallest:
                            runs.append((i, j, p))
                start = k + 1

        # Handle the last segment if it extends to the end of the string
        if n - p > start:
            i, j = start, n
            if j - i >= 2 * p:
                is_smallest = True
                for p_prime in range(1, p):
                    if (j - i - p_prime) <= lcp[i][i + p_prime]:
                        is_smallest = False
                        break
                if is_smallest:
                    runs.append((i, j, p))

    # Sort by i, then j
    runs.sort(key=lambda x: (x[0], x[1]))
    return runs

import itertools

def densest_circle(points):
    # Input validation
    if not isinstance(points, (list, tuple)):
        raise ValueError("points must be a list or tuple")

    n = len(points)
    # Check count constraint
    if n > 40:
        raise ValueError("Too many points")

    valid_points = []

    for p in points:
        if not isinstance(p, (list, tuple)):
            raise ValueError("Each point must be a list or tuple")
        if len(p) != 2:
            raise ValueError("Each point must have exactly 2 coordinates")

        x, y = p
        # Check for bool explicitly as bool is subclass of int
        if isinstance(x, bool) or isinstance(y, bool):
            raise ValueError("Coordinates must be ints, not bools")
        if not isinstance(x, int) or not isinstance(y, int):
            raise ValueError("Coordinates must be ints")

        if abs(x) > 10**6 or abs(y) > 10**6:
            raise ValueError("Coordinates out of range")

        valid_points.append((x, y))

    # Check distinctness
    if len(set(valid_points)) != n:
        raise ValueError("Points must be pairwise different")

    if n < 3:
        return (0, ())

    pts = valid_points
    best_k = 0
    best_indices = ()

    # Iterate over all triples
    for i, j, k in itertools.combinations(range(n), 3):
        x1, y1 = pts[i]
        x2, y2 = pts[j]
        x3, y3 = pts[k]

        # Check collinearity using determinant
        det = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1)

        if det == 0:
            continue

        # Circle parameters avoiding floating point
        dx1 = x2 - x1
        dy1 = y2 - y1
        dx2 = x3 - x1
        dy2 = y3 - y1

        c1 = x2*x2 - x1*x1 + y2*y2 - y1*y1
        c2 = x3*x3 - x1*x1 + y3*y3 - y1*y1

        num_h = c1 * dy2 - c2 * dy1
        num_k = dx1 * c2 - dx2 * c1
        den = 2 * det

        # R_num corresponds to r^2 * den^2
        term1 = x1 * den - num_h
        term2 = y1 * den - num_k
        R_num = term1 * term1 + term2 * term2

        # Count points on this circle
        current_indices = []
        for idx, (px, py) in enumerate(pts):
            val1 = px * den - num_h
            val2 = py * den - num_k
            if val1 * val1 + val2 * val2 == R_num:
                current_indices.append(idx)

        count = len(current_indices)

        if count > best_k:
            best_k = count
            best_indices = tuple(current_indices)
        elif count == best_k:
            current_tuple = tuple(current_indices)
            if current_tuple < best_indices:
                best_indices = current_tuple

        # Optimization: if we found a circle with all points, it's the best possible
        if best_k == n:
            break

    if best_k == 0:
        return (0, ())

    return (best_k, best_indices)
